<script lang="ts">
import Icon from '$lib/components/Icon.svelte';
import {enhance} from '$app/forms';
import {durationUnits,durationParts,formatDuration} from '$lib/duration';
let {data,form}=$props();let edit=$state<any>(null);
let checking=$state(false);
let showImport=$state(false);let importing=$state(false);
let copiedVoucher=$state<string|null>(null);let copyError=$state<string|null>(null);
async function copyCode(id:string,code:string){
  copyError=null;
  try{await navigator.clipboard.writeText(code);copiedVoucher=id;}
  catch{copiedVoucher=null;copyError=id;}
}

const names:Record<string,string>={sell:'Sell Internet',vouchers:'Voucher inventory','voucher-batches':'Voucher batches',packages:'Internet packages',sales:'Sales',payments:'Mobile payments','access-grants':'Access grants',sessions:'Wi-Fi sessions',staff:'Staff access',settings:'Network setup'};
const descriptions:Record<string,string>={sell:'Reserve stock, confirm cash received, and hand over a voucher.',vouchers:'Keep track of every code, from available stock to expiry.','voucher-batches':'Prepare prepaid stock in batches. Generating stock is not revenue.',packages:'Simple, time-based access. One device per voucher.',sales:'An accurate record of cash received and safe reversals.','access-grants':'Entitlement and authorization history — not a live connection monitor.',sessions:'Router-reported connections and data usage. Reports arrive every minute; stale sessions are not proof of an active connection.',staff:'Control who can sell internet and administer your shop.',settings:'Connection status, shared capacity and voucher checks.'};
const money=(n:number)=>'TZS '+new Intl.NumberFormat('en-TZ').format(n||0);
const date=(d:string)=>d?new Intl.DateTimeFormat('en-TZ',{dateStyle:'medium',timeStyle:'short',timeZone:'Africa/Dar_es_Salaam'}).format(new Date(d)):'—';
const label=(s:string)=>s.replaceAll('_',' ').toLowerCase();
const admin=$derived(data.staff.role==='ADMIN');
const headings:Record<string,string>={reference:'Reference',status:'Result',network:'Network',amount_tzs:'Amount',failure_reason:'What happened',payment_reference:'Payment ref',payment_method:'Paid by',name:'Package',price_tzs:'Price',duration_minutes:'Duration',download_mbps:'Down · Mbps',upload_mbps:'Up · Mbps',available:'In stock',active:'Active',code_mask:'Voucher',package_name:'Package',inventory_state:'Inventory',state:'Access',label:'Batch',quantity:'Quantity',created_at:'Created',receipt_number:'Receipt',total_tzs:'Total',client_mac:'Device',session_state:'Session',session_seconds:'Duration',upload_bytes:'Uploaded',download_bytes:'Downloaded',last_seen_at:'Last report',stopped_at:'Ended',display_name:'Name',role:'Role',enabled:'Enabled',provider:'Provider',proposed_expires_at:'Expiry'};
const columns=$derived(data.section==='packages'?['name','price_tzs','duration_minutes','download_mbps','upload_mbps','available','active']:data.section==='vouchers'?['code_mask','package_name','price_tzs','inventory_state','state']:data.section==='voucher-batches'?['label','quantity','created_at']:data.section==='sales'?['receipt_number','total_tzs','payment_method','network','payment_reference','created_at']:data.section==='payments'?['reference','status','network','amount_tzs','customer_phone','failure_reason','created_at']:data.section==='sessions'?['code_mask','package_name','client_mac','session_state','session_seconds','upload_bytes','download_bytes','last_seen_at','stopped_at']:data.section==='staff'?['display_name','role','enabled']:['code_mask','package_name','provider','state','proposed_expires_at']);
function printPage(){window.print();}
</script>
<svelte:head><title>{names[data.section]} · {data.brand}</title></svelte:head>
<div class="page-heading no-print"><div><p class="eyebrow">{data.section==='sell'?'AT THE COUNTER':'SHOP WORKSPACE'}</p><h1>{names[data.section]}</h1><p>{descriptions[data.section]}</p></div>{#if data.section==='packages'&&admin}<div class="heading-actions"><button class="button secondary" onclick={()=>showImport=!showImport}>{showImport?'Close import':'⭱ Import CSV'}</button><button class="button" onclick={()=>edit={name:'',price_tzs:1000,duration_minutes:60,duration_amount:1,duration_unit:'hours',description:'',active:true}}>＋ New package</button></div>{/if}</div>
{#if data.section==='packages'&&admin&&showImport}
<section class="panel no-print import-panel">
 <h2>Import packages from a file</h2>
 <p class="small muted">A CSV with the columns <code>name, description, price_tzs, duration_minutes, download_mbps, upload_mbps, active</code>. Only name, price and duration are required.</p>
 <p class="small muted"><strong>Duration is in minutes</strong> — 60 for an hour, 1440 a day, 10080 a week. Leave both speed columns blank for no limit, or fill both.</p>
 <form method="POST" enctype="multipart/form-data" use:enhance={()=>{importing=true;return async({update})=>{await update({reset:false});importing=false;};}}>
  <input type="hidden" name="op" value="import-packages">
  <label for="package-file">CSV file</label>
  <input id="package-file" name="file" type="file" accept=".csv,text/csv" required disabled={importing}>
  <div class="heading-actions">
   <a class="button secondary" href="/package-template" download>Download template</a>
   <button class="button" disabled={importing}>{importing?'Importing…':'Import packages'}</button>
  </div>
 </form>
 <p class="small muted">Nothing is imported unless every row is valid, so a rejected file leaves the catalogue untouched. Names already in the catalogue are refused rather than duplicated. Up to 200 packages per file.</p>
</section>
{/if}
{#if form?.error}<div class="notice error no-print" role="alert">{form.error}</div>{/if}{#if form?.message}<div class="notice no-print" role="status">{form.message}</div>{/if}
{#if form?.printed}<section class="print-preview panel"><div class="no-print print-toolbar"><h2>Ready to print</h2><button class="button" onclick={printPage}>Print / Save as PDF</button></div>{#if form.sale}<div class="receipt"><p class="eyebrow">{data.brand}</p><h2>Cash sale receipt</h2><p class="small">{form.sale.receipt_number}</p><p>{date(form.sale.created_at)} · Cashier: {form.sale.cashier_name}</p><strong class="receipt-total">{money(form.sale.total_tzs)}</strong><p>{form.sale.items.length} voucher(s) · Paid by cash</p><p class="small muted">Application receipt. Not a certified fiscal or tax receipt.</p></div>{/if}{#if form.issued!==undefined}<div class="notice no-print">{form.issued>0?`Issued ${form.issued} voucher${form.issued===1?'':'s'} — ${money(form.issuedTotal)} booked as revenue. They work as soon as a customer enters them.`:'Already issued. Reprinting the same codes; no new revenue recorded.'}</div>{/if}
<div class="voucher-sheet">{#each form.printed.items as v}<article class="printed-voucher">
 <div class="pv-top"><span class="pv-brand">{data.brand}</span><span class="pv-price">{money(v.price_tzs)}</span></div>
 <h3 class="pv-package">{v.package_name}</h3>
 <strong class="voucher-code">{v.code}</strong>
 <div class="pv-meta"><span>{formatDuration(v.duration_minutes)}</span>{#if v.download_mbps}<span>{v.download_mbps} Mbps</span>{/if}</div>
 <p class="pv-how">Connect to <strong>{data.brand}</strong>, then enter this code.</p>
 <div class="pv-foot"><span>One device · time runs from first use</span>{#if data.support}<span>{data.support}</span>{/if}</div>
 <button type="button" class="small-button no-print" aria-label={'Copy voucher code for '+v.package_name} onclick={()=>copyCode(v.id,v.code)}>{copiedVoucher===v.id?'Copied ✓':'Copy'}</button>
 <span class="sr-only no-print" role="status">{copiedVoucher===v.id?'Voucher code copied.':''}</span>
 {#if copyError===v.id}<p class="small no-print" role="alert">Copy unavailable. Select the code and copy manually.</p>{/if}
 {#if v.inventory_state==='AVAILABLE'}<span class="badge">NOT ISSUED — will not connect</span>{/if}
 {#if v.inventory_state==='VOID'}<span class="badge">VOID</span>{/if}
</article>{/each}</div></section>{/if}
{#if data.section==='sell'}
<div class="split no-print"><section class="panel"><p class="eyebrow">{form?.reservation?'STEP 2 · RECEIVE PAYMENT':'STEP 1 · SELECT STOCK'}</p><h2>{form?.reservation?'Confirm the cash sale':'Choose a package'}</h2>
{#if form?.reservation}<div class="sale-total"><span>{form.reservation.items.length} voucher(s)</span><strong>{money(form.reservation.total_tzs)}</strong><small>Reserved until {date(form.reservation.expires_at)}</small></div><ul class="line-items">{#each form.reservation.items as item}<li>{item.package_name}<strong>{money(item.price_tzs)}</strong></li>{/each}</ul><form method="POST"><input type="hidden" name="op" value="sell"><input type="hidden" name="reservation_id" value={form.reservation.id}><input type="hidden" name="idempotency_key" value={form.idempotency_key}><label>Customer name <small>Optional</small><input name="customer_name" maxlength="100"></label><label>Phone <small>Optional</small><input name="customer_phone" maxlength="30"></label><label>Notes <small>Optional</small><textarea name="notes" maxlength="500"></textarea></label><label class="checkbox"><input type="checkbox" name="cash_received" required>I have received {money(form.reservation.total_tzs)} in cash.</label><button class="button full">Record sale & prepare receipt →</button><a class="text-link" href="/sell">Start again (reservation releases after 5 minutes)</a></form>
{:else}<form method="POST"><input type="hidden" name="op" value="reserve"><label>Package<select name="package_id" required><option value="">Select a package</option>{#each data.packages.items as p}<option value={p.id} disabled={!p.available}>{p.name} · {money(p.price_tzs)} · {p.available} available</option>{/each}</select></label><label>Number of vouchers<input name="quantity" type="number" min="1" max="100" value="1" required></label><p class="small muted">Final prices come from the reserved vouchers. Existing stock keeps its original price after package edits.</p><button class="button full">Reserve stock →</button></form>{/if}</section><section class="panel accent"><p class="eyebrow">A SIMPLE HANDOVER</p><h2>Cash first.<br>Connection next.</h2><p>After recording the sale, print a receipt or share the voucher privately with the customer.</p><div class="rule"><strong>The clock hasn’t started yet.</strong><p>Validity begins when the customer first activates the code on their device.</p></div><p class="small">A reserved voucher is held for five minutes. Unsold codes cannot connect.</p></section></div>
{:else if data.section==='settings'}{#if data.network.provider==='mikrotik'}<div class="settings-grid"><section class="panel"><div class="section-heading"><div><p class="eyebrow">MIKROTIK L009 + EAP225-OUTDOOR</p><h2>Connection & capacity</h2></div><span class="action-icon"><Icon name="wifi"/></span></div><div class="notice">{data.network.radius_enabled?'Live voucher authentication is configured. The RADIUS service handles login, speed limits and the fixed expiry.':'The portal API is in test mode. A separately deployed RADIUS service can already authenticate real vouchers.'}</div><dl class="details"><dt>API authorization mode</dt><dd><span class="badge" class:warning={!data.network.radius_enabled}>{data.network.radius_enabled?'Live · RADIUS':'Test mode'}</span></dd><dt>Fibre download</dt><dd>{data.network.download_mbps} Mbps shared</dd><dt>Fibre upload</dt><dd>{data.network.upload_mbps?data.network.upload_mbps+' Mbps':'Not confirmed'}</dd><dt>Router credentials</dt><dd>{data.network.configured?'Configured':'Not configured'}</dd><dt>Last router check</dt><dd>{date(data.network.last_check)}</dd><dt>Check result</dt><dd>{data.network.ok===null?'Not checked':data.network.ok?'Router reachable':'Needs attention'}</dd></dl><form method="POST" use:enhance={()=>{checking=true;return async({update})=>{try{await update();}finally{checking=false;}};}}><input type="hidden" name="op" value="mikrotik-test"><button class="button" disabled={checking}><Icon name="wifi" size={18}/>{checking?'Checking router…':'Check MikroTik connection'}</button></form>{#if data.network.message}<p class="check-result" role="status">{data.network.message}</p>{/if}</section><section class="panel setup-guide"><p class="eyebrow">LAUNCH CHECKS</p><h2>Verify on a customer device.</h2><p>A successful router check confirms management access. Test the full voucher journey on the shop Wi-Fi.</p><ol class="steps"><li><strong>Connect with a sold voucher</strong><p>Confirm browsing and the package speed limit.</p></li><li><strong>Reconnect on the same device</strong><p>The original expiry must stay unchanged. A second device must be rejected.</p></li><li><strong>Wait for permanent expiry</strong><p>Internet stops and the expired code cannot log in again.</p></li><li><strong>Check session reports</strong><p>Review connection times and data usage under Wi-Fi sessions.</p></li></ol><a href="/sessions" class="small-button">Open Wi-Fi sessions <Icon name="arrow" size={15}/></a><details class="setup-details"><summary>Why does the portal show test mode?</summary><p>The API and web deployment must both use live mode after commissioning. RADIUS runs separately, so a working voucher alone does not change this label.</p><p class="small">Set <code>NETWORK_PROVIDER=mikrotik</code>, <code>OMADA_MODE=live</code> and <code>MIKROTIK_RADIUS_ENABLED=true</code> in the API environment, align the web environment, and recreate the containers.</p></details></section></div>{:else}<div class="split"><section class="panel"><p class="eyebrow">OMADA EXTERNAL PORTAL</p><h2>{data.integration.mode==='mock'?'Simulation is enabled':'Live controller mode'}</h2><p>{data.integration.message}</p><dl class="details"><dt>Last connection check</dt><dd>{date(data.integration.last_check)}</dd><dt>Result</dt><dd>{data.integration.ok===null?'Not checked':data.integration.ok?'Login successful':'Check failed'}</dd><dt>Expiry</dt><dd>{data.integration.capabilities.expiry}</dd><dt>Disconnect / reconciliation</dt><dd>Unsupported</dd><dt>Packages</dt><dd>Time only · One device</dd></dl><form method="POST"><input type="hidden" name="op" value="test"><button class="button">Test operator login</button></form><p class="small muted">Login success does not verify real AP authorization or expiry.</p></section><section class="panel"><h2>Keep management private</h2><p>Controller credentials and the verified expiry profile are configured on the server. They are never sent to the browser.</p><p>Complete the commissioning checklist before serving paying customers in live mode.</p><p class="notice">Revoking a grant blocks future authorization. Existing network access may continue until the controller’s expiry.</p><h3>Brand & support</h3><p>{data.brand}</p><p class="small muted">Set WIFI_BRAND and WIFI_SUPPORT_CONTACT in the deployment environment.</p></section></div>
{/if}
{:else}
{#if data.section==='voucher-batches'}<section class="panel no-print"><h2>Generate stock</h2><form method="POST" class="inline-form"><input type="hidden" name="op" value="batch"><label>Package<select name="package_id" required><option value="">Choose package</option>{#each data.packages.items.filter((p:any)=>p.active) as p}<option value={p.id}>{p.name} · {money(p.price_tzs)}</option>{/each}</select></label><label>Quantity<input name="quantity" type="number" min="1" max="1000" value="10" required></label><label>Batch label <small>Optional</small><input name="label" placeholder="e.g. Saturday counter stock" maxlength="100"></label><button class="button">Generate vouchers</button></form></section>{/if}
{#if data.section==='staff'}<p class="notice">Create new staff securely with <code>pnpm staff:create</code>. There is no public registration. Disabling access takes effect on the next application request.</p>{/if}
{#if data.section==='packages'&&edit}<section class="panel no-print"><div class="print-toolbar"><h2>{edit.id?'Edit package':'New package'}</h2><button class="text-button" onclick={()=>edit=null}>Close</button></div><form method="POST"><input type="hidden" name="op" value="package"><input type="hidden" name="id" value={edit.id||''}><div class="form-grid"><label>Name<input name="name" value={edit.name} required maxlength="100"></label><label>Price (whole TZS)<input name="price_tzs" type="number" min="1" max="10000000" value={edit.price_tzs} required></label><div><div class="form-grid"><label>Duration<input name="duration_amount" type="number" min="1" step="1" max={Math.floor(525600/(durationUnits.find(unit=>unit.value===edit.duration_unit)?.minutes||1))} bind:value={edit.duration_amount} required></label><label>Time unit<select name="duration_unit" bind:value={edit.duration_unit}>{#each durationUnits as unit}<option value={unit.value}>{unit.label}</option>{/each}</select></label></div><div class="row-actions" aria-label="Common durations">{#each [{label:'1 hour',amount:1,unit:'hours'},{label:'24 hours',amount:24,unit:'hours'},{label:'1 week',amount:1,unit:'weeks'},{label:'1 month',amount:1,unit:'months'}] as preset}<button type="button" class="small-button" onclick={()=>{edit.duration_amount=preset.amount;edit.duration_unit=preset.unit;}}>{preset.label}</button>{/each}</div><p class="small muted">One month = 30 days. Validity starts at first activation, not purchase.</p></div><label>Description<textarea name="description" maxlength="1000">{edit.description}</textarea></label></div>{#if data.networkProvider==='mikrotik'}<fieldset><legend>Package speed limits</legend><div class="form-grid"><label>Download (Mbps)<input name="download_mbps" type="number" min="1" max={data.wanDownload} step="1" value={edit.download_mbps??''} placeholder="e.g. 10"></label><label>Upload (Mbps)<input name="upload_mbps" type="number" min="1" max={data.wanUpload||10000} step="1" value={edit.upload_mbps??''} placeholder="e.g. 5"></label></div><p class="small muted">Set both speeds, or leave both blank for existing time-only packages. Your {data.wanDownload} Mbps download connection is shared by all customers. {data.wanUpload?'Upload capacity: '+data.wanUpload+' Mbps.':'Upload capacity still needs to be confirmed.'}</p><p class="notice">{data.radiusEnabled?'New vouchers carry these limits to MikroTik through RADIUS. Existing vouchers keep their original limits.':'Speed settings are saved with new vouchers. The API is in test mode; a separate RADIUS service may already enforce them. Verify on a customer device before launch.'}</p></fieldset>{:else}<p class="notice">Package speed limits are not supported by the current Omada integration.</p>{/if}<label class="checkbox"><input name="active" type="checkbox" checked={edit.active}>Active — allow new stock and sales</label><button class="button">Save package</button><p class="small muted">Existing vouchers retain their original package name, price, duration and speed settings.</p></form></section>{/if}
<section class="panel list-panel no-print"><form method="GET" class="filter-bar"><label class="search-label"><span class="sr-only">Search records</span><input name="q" value={data.query.q||''} placeholder="Search records…"></label>{#if ['vouchers','access-grants'].includes(data.section)}<select name="state" aria-label="Filter by status"><option value="">All statuses</option>{#each ['AVAILABLE','SOLD','VOID','PENDING','ACTIVE','EXPIRED','REVOKED','NEEDS_REVIEW'] as state}<option value={state} selected={data.query.state===state}>{label(state)}</option>{/each}</select>{/if}{#if data.section==='vouchers'&&data.packages}<select name="package_id" aria-label="Filter by package"><option value="">All packages</option>{#each data.packages.items as item (item.id)}<option value={item.id} selected={data.query.package_id===item.id}>{item.name}</option>{/each}</select>{/if}<select name="sort" aria-label="Sort"><option value="newest">Newest first</option><option value="oldest" selected={data.query.sort==='oldest'}>Oldest first</option></select><button class="button secondary">Apply</button></form>
{#if data.list.items.length===0}<div class="empty"><span>◇</span><h2>No records to show</h2><p>{data.query.q||data.query.state?'Try changing your search or filters.':data.section==='packages'?'Create a package to prepare your first vouchers.':data.section==='sales'?'Your recorded cash sales will appear here.':'Records will appear here as your shop starts using the system.'}</p></div>{:else}<div class="table-wrap"><table><thead><tr>{#each columns as col}<th>{headings[col]||label(col)}</th>{/each}<th>Actions</th></tr></thead><tbody>{#each data.list.items as row}<tr>{#each columns as col}<td>{#if ['state','session_state','inventory_state','role'].includes(col)}<span class="badge" class:warning={['NEEDS_REVIEW','STALE','PENDING','REVOKED_PENDING_DISCONNECT'].includes(row[col])} class:inactive={['EXPIRED','REVOKED','VOID','STOPPED'].includes(row[col])}>{row[col]?label(row[col]):row.inventory_state==='SOLD'?'sold, unused':'—'}</span>{:else if col==='session_seconds'}{Math.floor(row[col]/60)} min{:else if col==='upload_bytes'||col==='download_bytes'}{(Number(row[col])/1048576).toFixed(2)} MiB{:else if col==='duration_minutes'}{formatDuration(row[col])}{:else if col.endsWith('_tzs')}{money(row[col])}{:else if col.endsWith('_at')}{date(row[col])}{:else if typeof row[col]==='boolean'}{row[col]?'Yes':'No'}{:else if col==='receipt_number'}<a class="text-link" href={'/sales?sale='+row.id}>{row[col].slice(0,15)}…</a>{:else}{row[col]??'—'}{/if}</td>{/each}<td><div class="row-actions">
{#if data.section==='packages'&&admin}<button class="small-button" onclick={()=>edit={...row,...durationParts(row.duration_minutes)}}>Edit</button>{:else if data.section==='voucher-batches'}<form method="POST"><input type="hidden" name="op" value="issue-batch"><input type="hidden" name="id" value={row.id}><button class="small-button">Issue &amp; print</button></form><form method="POST"><input type="hidden" name="op" value="print-batch"><input type="hidden" name="id" value={row.id}><button class="small-button">Reprint</button></form>{:else if data.section==='sales'}<form method="POST"><input type="hidden" name="op" value="print-sale"><input type="hidden" name="id" value={row.id}><button class="small-button">Print receipt</button></form>{#if admin}<details><summary>Reverse</summary><form method="POST" class="confirmation"><input type="hidden" name="op" value="reverse"><input type="hidden" name="id" value={row.id}><p>This permanently voids all codes. Only completely unused sales qualify.</p><label>Reason<textarea name="reason" minlength="3" maxlength="500" required></textarea></label><button class="button danger">Confirm reversal</button></form></details>{/if}{:else if data.section==='vouchers'&&admin}<form method="POST"><input type="hidden" name="op" value="reveal"><input type="hidden" name="id" value={row.id}><button class="small-button">Reveal</button></form>{#if row.inventory_state==='AVAILABLE'}<details><summary>Void</summary><form method="POST" class="confirmation"><input type="hidden" name="op" value="void"><input type="hidden" name="id" value={row.id}><p>This code will never be usable again.</p><label>Reason<textarea name="reason" minlength="3" maxlength="500" required></textarea></label><button class="button danger">Permanently void</button></form></details>{/if}{:else if data.section==='access-grants'&&row.state!=='REVOKED'}<details><summary>Revoke</summary><form method="POST" class="confirmation"><input type="hidden" name="op" value="revoke"><input type="hidden" name="id" value={row.id}><p>Blocks future authorization. Network access may continue until controller expiry.</p><label>Reason<textarea name="reason" minlength="3" maxlength="500" required></textarea></label><button class="button danger">Revoke access</button></form></details>{:else if data.section==='staff'&&row.id!==data.staff.id}<details><summary>Edit access</summary><form method="POST" class="confirmation"><input type="hidden" name="op" value="staff"><input type="hidden" name="id" value={row.id}><label>Role<select name="role"><option selected={row.role==='CASHIER'}>CASHIER</option><option selected={row.role==='ADMIN'}>ADMIN</option></select></label><label class="checkbox"><input type="checkbox" name="enabled" checked={row.enabled}>Enabled</label><button class="button">Save access</button></form></details>{/if}
</div></td></tr>{/each}</tbody></table></div>{/if}<div class="pagination"><span>Page {data.list.page} · Up to 25 records</span><div>{#if data.list.page>1}<a class="small-button" href={'?'+new URLSearchParams({...data.query,page:String(data.list.page-1)})}>← Previous</a>{/if}{#if data.list.has_more}<a class="small-button" href={'?'+new URLSearchParams({...data.query,page:String(data.list.page+1)})}>Next →</a>{/if}</div></div></section>
{#if data.sale}<section class="panel"><h2>Sale details</h2><p>{data.sale.receipt_number}</p><p>{date(data.sale.created_at)} · {data.sale.cashier_name}</p><strong>{money(data.sale.total_tzs)}</strong>{#if data.sale.reversal_reason}<p class="notice">Reversed: {data.sale.reversal_reason}</p>{/if}<ul>{#each data.sale.items as item}<li>{item.package_name} · {item.code_mask} · {money(item.price_tzs)}</li>{/each}</ul></section>{/if}
{#if data.attempts?.items.length}<section class="panel"><h2>Authorization needs review</h2><p>Verify the client’s authorization and deadline in the controller. Record evidence before deciding. Never assume a timeout means failure.</p>{#each data.attempts.items as attempt}<form method="POST" class="review-form"><input type="hidden" name="op" value="review"><input type="hidden" name="id" value={attempt.id}><p><strong>{attempt.evidence?.code}</strong> · Deadline: {date(attempt.deadline)}</p><label>Verified outcome<select name="decision"><option value="ACCEPTED">Controller confirms authorization</option><option value="REJECTED">Controller confirms no authorization</option></select></label><label>Evidence and reason<textarea name="reason" minlength="10" maxlength="500" required placeholder="Controller record, checked time, client and observed deadline"></textarea></label><button class="button secondary">Record verified outcome</button></form>{/each}</section>{/if}
{/if}
